#[test]
fn the_synthetic_sdk_validates_without_building_anything() {
    Synthetic::validate_header_names().unwrap();
}

#[test]
fn every_kind_of_endpoint_prepares() {
    let api = Synthetic::new(
        reqwest::Client::new(),
        SyntheticConfig { token: "t".into() },
    );
    let s = api.s39();
    for result in [
        s.e0().prepare().map(drop),
        s.e1().prepare().map(drop),
        s.e2().prepare().map(drop),
        s.e3().prepare().map(drop),
        s.e4().prepare().map(drop),
        s.e5().prepare().map(drop),
    ] {
        result.unwrap();
    }
}
